namespace sv_52a9437d7d104d25bc763c29e71f3622.Client.Models;

public class Shipment
{
    public required string TrackingNumber { get; set; }
    public required string Status { get; set; }
    public required string Location { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public List<StatusUpdate> StatusUpdates { get; set; } = [];
}

public class StatusUpdate
{
    public required string Description { get; set; }
    public required string Location { get; set; }
    public DateTime Timestamp { get; set; }
}

using sv_52a9437d7d104d25bc763c29e71f3622.Client.Models;

namespace sv_52a9437d7d104d25bc763c29e71f3622.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_52a9437d7d104d25bc763c29e71f3622.Client.Models;

namespace sv_52a9437d7d104d25bc763c29e71f3622.Client.Services;

public class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        return await http.GetFromJsonAsync<Shipment?>($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);
    }
}

using sv_52a9437d7d104d25bc763c29e71f3622.Client.Models;
using sv_52a9437d7d104d25bc763c29e71f3622.Client.Services;

namespace sv_52a9437d7d104d25bc763c29e71f3622.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = DateTime.Today.AddDays(2),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Los Angeles, CA", Timestamp = DateTime.Today.AddDays(-3).AddHours(9) },
                new StatusUpdate { Description = "Departed facility", Location = "Los Angeles, CA", Timestamp = DateTime.Today.AddDays(-3).AddHours(14) },
                new StatusUpdate { Description = "Arrived at sorting center", Location = "Memphis, TN", Timestamp = DateTime.Today.AddDays(-1).AddHours(6) },
                new StatusUpdate { Description = "In transit to destination", Location = "Memphis, TN", Timestamp = DateTime.Today.AddHours(8) }
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = DateTime.Today.AddDays(-1),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Chicago, IL", Timestamp = DateTime.Today.AddDays(-5).AddHours(10) },
                new StatusUpdate { Description = "In transit", Location = "Columbus, OH", Timestamp = DateTime.Today.AddDays(-3).AddHours(16) },
                new StatusUpdate { Description = "Out for delivery", Location = "New York, NY", Timestamp = DateTime.Today.AddDays(-1).AddHours(7) },
                new StatusUpdate { Description = "Delivered — signed by J. Smith", Location = "New York, NY", Timestamp = DateTime.Today.AddDays(-1).AddHours(14) }
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Seattle, WA",
            EstimatedDelivery = DateTime.Today.AddDays(5),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Label created", Location = "Seattle, WA", Timestamp = DateTime.Today.AddHours(-2) },
                new StatusUpdate { Description = "Awaiting carrier pickup", Location = "Seattle, WA", Timestamp = DateTime.Today.AddHours(-1) }
            ]
        }
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_52a9437d7d104d25bc763c29e71f3622.Client.Models
@using sv_52a9437d7d104d25bc763c29e71f3622.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="card mt-4">
        <div class="card-body">
            <p class="placeholder-glow">
                <span class="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                Loading shipment <strong>@TrackingNumber</strong>&hellip;
            </p>
        </div>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger mt-4" role="alert">
        <strong>Something went wrong.</strong> @_errorMessage
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning mt-4" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <div class="card mt-4">
        <div class="card-header">
            <h4 class="mb-0">Shipment @_shipment.TrackingNumber</h4>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-3">Status</dt>
                <dd class="col-sm-9">@_shipment.Status</dd>

                <dt class="col-sm-3">Location</dt>
                <dd class="col-sm-9">@_shipment.Location</dd>

                <dt class="col-sm-3">Estimated Delivery</dt>
                <dd class="col-sm-9">@(_shipment.EstimatedDelivery?.ToString("D") ?? "—")</dd>
            </dl>
        </div>
    </div>

    @if (_shipment.StatusUpdates.Count > 0)
    {
        <h5 class="mt-4">Tracking History</h5>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Date &amp; Time</th>
                    <th>Location</th>
                    <th>Description</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Location</td>
                        <td>@update.Description</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request (handles navigation to a different tracking number)
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Request was intentionally cancelled — do nothing.
            return;
        }
        catch (TaskCanceledException)
        {
            Logger.LogError("Request timed out for shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException)
        {
            Logger.LogError("Request timed out for shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "We couldn't load the shipment details. Please try again later.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

